const config_agenda = AGENDAS[tipoAgenda] || AGENDAS['penha'];

function acharIdAtendimento(o) {
    for (const key of Object.keys(o)) {
        const norm = key.toLowerCase().replace(/[^a-z]/g, '');
        if (norm.includes('atendi') && norm.includes('id') && o[key]) {
            return o[key].toString();
        }
    }
    return '';
}
const idAtendimento = body.id_atendimento || body.atendimento_id || body.session_id || body.sessionId || acharIdAtendimento(body) || '';

// CONFIGURAÇÃO DO KANBAN (painel único, compartilhado pelas 3 unidades)
const KANBAN = {
    helena_token: 'pn_FeGSOXOMB8wT3X4VfS4QoxrxwMBxWgKsSZKJgH8qkPs',
